// Actual Creature::AIM_Initialize and Unit-owned queues,with a controlled payload.
#include "ActorQueueLifetimeNative.h"
template<class F>static void RunLifetimeAdmission(Creature&actor,Creature&peer,uint32 index,bool combat,bool other){Creature&owner=other?peer:actor;auto pump=[&](uint32 ms){PumpQueue(owner,ms,combat);};
 Observe::Reset();auto live=new F(&actor,&peer);Require(actor.AIM_Initialize(live),"install live admission AI");live->Queue(index);pump(122);Require(!Observe::calls,"controlled native admission clock");pump(1);Require(Observe::calls==1&&Observe::actor==&actor,"live native AI enters payload");pump(60000);Require(Observe::calls==1,"native admitted callback once");
 Observe::Reset();auto retired=new F(&actor,&peer);Require(actor.AIM_Initialize(retired),"install retire witness");retired->Queue(index);Require(actor.AIM_Initialize(new NullCreatureAI(&actor)),"actual source AI destructor invalidates captured weak anchor");pump(123);Require(!Observe::calls,"retired native AI cannot enter original body");
 auto cancelled=new F(&actor,&peer);Require(actor.AIM_Initialize(cancelled),"install cancellation witness");cancelled->Queue(index);if(combat)owner.KillAllDelayedCombats();else owner.KillAllDelayedEvents();pump(123);Require(!Observe::calls,"native queue cancellation retained");
 auto suspended=new F(&actor,&peer);Require(actor.AIM_Initialize(suspended),"install surviving AI witness");suspended->Queue(index);auto saved=actor.GetAI();bool enabled=actor.IsAIEnabled;actor.SetAI(nullptr);actor.IsAIEnabled=false;pump(123);actor.SetAI(saved);actor.IsAIEnabled=enabled;Require(Observe::calls==1,"surviving temporarily inactive AI retains original admission");Require(actor.AIM_Initialize(new NullCreatureAI(&actor)),"clean actual witness AI");}
